insert into public.play_tags (play_id, tag_id)
select p.id, tg.id
from pt
join public.formations f on f.family = pt.family and f.name = pt.formation
join public.playbooks b on b.id = f.playbook_id and b.name = 'Atlanta'
join public.plays p on p.formation_id = f.id and lower(p.play_name) = lower(pt.play_name) and p.owner_id is null
join public.tags tg on lower(tg.name) = lower(pt.tag)
on conflict do nothing;

